 const oldDashboard=renderDashboard;renderDashboard=function(data){oldDashboard(data);$('wsClient').textContent=data.client==='demo-rio'?'Founder test workspace':data.client_name||data.client;$('wsTopStatus').textContent=data.impersonated?'Read-only operator preview':data.client==='demo-rio'?'Demo data · private workspace':'Private workspace';if(['home','content','plans','team','todos'].includes(route)||route.startsWith('revenue')){park();render();}if(!loaded)refreshRecords().then(()=>{if(!dirty&&(['home','copy','copy/drafts','youtube','youtube/projects','youtube/design','youtube/designs','leads','tracker'].includes(route)||route.startsWith('copy/edit/')||route.startsWith('youtube/edit/')||route.startsWith('youtube/design/')||route.startsWith('leads/'))){park();render();}});};
 for(const name of ['proof','performance','integrations']){const eventName='pulsify:'+name;document.addEventListener(eventName,()=>{if((name==='proof'&&route==='media')||(name==='integrations'&&route==='access')){park();render();}});}
 document.addEventListener('pulsify:project-open',e=>{const next='studio/project/'+e.detail.format+'/'+e.detail.id;if(route!==next)go(next,{force:true});});
 document.addEventListener('click',e=>{const b=e.target.closest('#focusSequenceLogButton');if(b){e.preventDefault();action('log-sequence',b);}},true);
 window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});
 document.addEventListener('pulsify:slide-render',()=>{if($('wsPanelAI')||!$('sxCopySlide'))return;const b=document.createElement('button');b.id='wsPanelAI';b.className='sx-secondary';b.textContent='Draft this panel with AI';$('sxCopySlide').before(b);b.onclick=()=>{const c=window.PulsifyStudio.current();if(!c.editable)return toast('This project is read-only.');openDrawer('Write this story panel',`<div class="ws-form"><label>Panel brief<textarea id="wsPanelBrief"></textarea></label>${btn('Generate panel copy','panel-ai-generate')}<label>Suggested copy<textarea id="wsPanelResult" style="min-height:170px"></textarea></label><button class="ws-button" id="wsPanelApply" data-ws="panel-ai-apply" disabled>Use this copy</button><p class="ws-note">Review the wording and facts before applying. Your existing panel stays intact until you choose Use this copy.</p></div>`);$('wsPanelBrief').value='Sequence: '+c.project.topic+'\nType: '+c.project.type+'\nThis panel must: '+(c.slide.job||c.slide.role)+'\nSequence brief: '+(c.project.intent||'')+'\nUse only verified facts from the saved client context. Write at most 35 words.';};});
