 Promise.all([fetch('/portal/thumbnail-library.json').then(r=>r.json()).then(data=>{assets=data;}).catch(()=>{toast('The thumbnail archive could not load. Refresh to try again.');}),api('/api/copywriter').then(d=>{aiAvailable=d.available;}).catch(()=>{aiAvailable=false;})]).then(()=>{if(!dirty&&(['home','youtube','youtube/gallery','youtube/design','youtube/designs','copy'].includes(route)||route.startsWith('youtube/design/')||route.startsWith('leads/'))){park();render();}});
 refreshRecords().then(()=>{if(!dirty&&(['home','copy','copy/drafts','youtube','youtube/projects','youtube/design','youtube/designs','leads','tracker'].includes(route)||route.startsWith('copy/edit/')||route.startsWith('youtube/edit/')||route.startsWith('youtube/design/')||route.startsWith('leads/'))){park();render();}});
